/* qiaomu-reader plugin stylesheet.
   Organised by feature area, top to bottom: reader shell and text flow; PDF
   pages and the zoom lightbox; floating chrome; slide-over panels; the
   library; highlights; the plugin settings tab; modals; motion tokens and the
   responsive sizing layer; the AI assistant; and the composite navigation
   bar. Rules keep the qiaomu-reader- prefix; shared sizing lives in the
   responsive-token block under :root. */

/* ── Reader shell, paginated flow, text selection ─────────────────────────── */
.workspace-leaf-content[data-type="qiaomu-reader"] > .view-header { display:none; }
.view-content.qiaomu-reader-view { display:flex; flex-direction:column; height:100%; background:var(--qiaomu-reader-bg,var(--background-primary)); overflow:hidden; position:relative; padding:0; margin:0; box-sizing:border-box; }
.qiaomu-reader-content img { max-width:100%; height:auto; display:block; margin:8px auto; }
.qiaomu-reader-content figure { margin:8px auto; text-align:center; }
.qiaomu-reader-content figure img { margin:0 auto; }
.qiaomu-reader-content figcaption { font-size:.82em; opacity:.7; margin-top:4px; text-align:center; }
/* Phone-side text selection is painted by qiaomuReaderPaintSelection: WebKit
   does not draw a dependable selection inside a transformed multi-column page,
   so without this rule the live range existed but stayed invisible. The fill is
   semi-transparent so the letters remain readable underneath — it reads as a
   marker stroke, not a solid block. It intentionally uses a literal colour
   instead of var(--qiaomu-reader-accent): a highlight pseudo-element does not
   resolve custom properties the way an ordinary rule does, and an unresolved
   colour paints nothing at all — the exact defect this rule guards against.
   The search-hit rule next door (qiaomu-reader-found) made the same trade-off,
   and this blue stays legible on the light, sepia and dark papers alike. */
::highlight(qiaomu-reader-selection) { background-color: rgba(85, 72, 217, 0.28); }
.qiaomu-reader-eink ::highlight(qiaomu-reader-selection) { background-color: rgba(0, 0, 0, 0.22); }
.qiaomu-reader-content, .qiaomu-reader-flow, .qiaomu-reader-flow p, .qiaomu-reader-flow h1, .qiaomu-reader-flow h2, .qiaomu-reader-flow h3, .qiaomu-reader-flow h4 { -webkit-user-select:text; user-select:text; -webkit-touch-callout:default; }

/* ── PDF pages, lazy figures, zoom lightbox ──────────────────────────────── */
.qiaomu-reader-content .qiaomu-reader-pdf-page-img { max-width:100%; width:auto; height:auto; object-fit:contain; margin:6px auto; border-radius:10px; border:1px solid var(--qiaomu-reader-border,#ddd9ce); }
.qiaomu-reader-pdf-page-img, .qiaomu-reader-content img, .qiaomu-reader-flow img { cursor:zoom-in; }
img.qiaomu-reader-pdf-lazy:not([data-loaded="1"]) { background:color-mix(in srgb,var(--qiaomu-reader-text,#808080) 7%,transparent); cursor:default; }
.qiaomu-reader-pdf-text-layer.qiaomu-reader-pdf-text-placeholder { display:none; }
.qiaomu-reader-pdf-page-surface.qiaomu-reader-pdf-rendering::after { content:""; position:absolute; inset:0; z-index:3; pointer-events:none; background:linear-gradient(100deg,rgba(255,255,255,0) 30%,rgba(255,255,255,.72) 48%,rgba(255,255,255,0) 66%),color-mix(in srgb,var(--qiaomu-reader-text,#808080) 9%,#fff); background-size:220% 100%; animation:qiaomu-reader-pdf-page-loading 1.05s ease-in-out infinite; }
@keyframes qiaomu-reader-pdf-page-loading { from { background-position:100% 0; } to { background-position:-100% 0; } }
@media (prefers-reduced-motion:reduce) { .qiaomu-reader-pdf-page-surface.qiaomu-reader-pdf-rendering::after { animation:none; } }
.qiaomu-reader-lightbox { position:fixed; inset:0; z-index:9999; background:rgba(8,8,12,.93); -webkit-backdrop-filter:blur(4px); backdrop-filter:blur(4px); display:flex; overflow:auto; opacity:0; transition:opacity .18s ease; }
.qiaomu-reader-lightbox.qiaomu-reader-lightbox-on { opacity:1; }
.qiaomu-reader-lightbox img { margin:auto; display:block; width:auto; height:auto; max-width:calc(100vw - 40px); max-height:calc(100vh - 40px); border-radius:8px; background:#fff; box-shadow:0 24px 90px rgba(0,0,0,.6); cursor:zoom-in; }
.qiaomu-reader-lightbox img.qiaomu-reader-lightbox-zoom { max-width:none; max-height:none; width:auto; height:auto; cursor:zoom-out; border-radius:0; }
.qiaomu-reader-lightbox-close { position:fixed; top:14px; right:16px; width:42px; height:42px; border-radius:50%; background:rgba(255,255,255,.16); color:#fff; font-size:20px; line-height:42px; text-align:center; cursor:pointer; z-index:2; -webkit-backdrop-filter:blur(6px); backdrop-filter:blur(6px); transition:background .14s,transform .1s; }
.qiaomu-reader-lightbox-close:hover { background:rgba(255,255,255,.3); }
.qiaomu-reader-lightbox-close:active { transform:scale(.9); }
.qiaomu-reader-lightbox-hint { position:fixed; bottom:16px; left:0; right:0; text-align:center; color:rgba(255,255,255,.6); font-size:12px; font-family:'Inter',system-ui,sans-serif; pointer-events:none; }
.qiaomu-reader-content .qiaomu-reader-pdf-page-img.qiaomu-reader-pdf-heavy { display:flex; align-items:center; justify-content:center; background:var(--qiaomu-reader-lib-bg,#f3f1ec); border-style:dashed; color:var(--qiaomu-reader-muted,#8a8578); font-size:13px; padding:10px; text-align:center; }
.qiaomu-reader-content .qiaomu-reader-pdf-figure { margin:0 0 14px; text-align:center; }
.qiaomu-reader-content .qiaomu-reader-pdf-figure img { margin:0 auto; }

/* ── Resume flash and progress hairline ──────────────────────────────────── */
.qiaomu-reader-resume-flash { animation:qiaomu-reader-resume-flash 2.3s ease-out; border-radius:5px; }
@keyframes qiaomu-reader-resume-flash { 0% { background:color-mix(in srgb, var(--qiaomu-reader-accent) 34%, transparent); box-shadow:0 0 0 6px color-mix(in srgb, var(--qiaomu-reader-accent) 12%, transparent); } 70% { background:color-mix(in srgb, var(--qiaomu-reader-accent) 24%, transparent); } 100% { background:transparent; box-shadow:0 0 0 6px transparent; } }
.qiaomu-reader-pbar { position:absolute; top:0; left:0; right:0; height:3px; background:rgba(0,0,0,.06); z-index:20; pointer-events:none; }
.qiaomu-reader-pbar-fill { height:100%; width:0%; background:linear-gradient(90deg,var(--qiaomu-reader-accent,#5548d9),color-mix(in srgb,var(--qiaomu-reader-accent) 60%,#fff)); border-radius:0 2px 2px 0; transition:width .5s cubic-bezier(.4,0,.2,1); }

/* ── Edge-aligned chrome: bars, buttons and location readout ─────────────── */
.qiaomu-reader-top { position:absolute; top:0; left:0; right:0; height:40px; display:flex; align-items:center; padding:4px 8px; gap:6px; box-sizing:border-box; border:0; border-bottom:1px solid; border-radius:0; box-shadow:none; z-index:16; }
.qiaomu-reader-top-title { flex:1 1 auto; min-width:0; text-align:left; font-size:12px; font-weight:500; font-family:'Inter',system-ui,sans-serif; color:var(--qiaomu-reader-muted,var(--text-muted)); opacity:1; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.qiaomu-reader-top-right { display:flex; gap:2px; align-items:center; }
.qiaomu-reader-ibtn { width:36px; height:36px; padding:0; display:flex; align-items:center; justify-content:center; box-sizing:border-box; border:1px solid var(--background-modifier-border); box-shadow:none; background:color-mix(in srgb,var(--text-normal) 4%,transparent); border-radius:10px; cursor:pointer; color:var(--text-muted); opacity:.82; transition:opacity .15s,background .13s,border-color .13s,transform .1s; flex-shrink:0; }
.qiaomu-reader-ibtn:hover { opacity:1; background:var(--background-modifier-hover); border-color:color-mix(in srgb,var(--text-muted) 35%,var(--background-modifier-border)); }
.qiaomu-reader-ibtn:active { transform:scale(.87); }
.qiaomu-reader-ibtn svg { width:18px; height:18px; }
.qiaomu-reader-pdf-zoom-control { height:36px; display:none; grid-template-columns:30px 52px 30px 30px; align-items:stretch; flex:none; overflow:hidden; border:1px solid var(--background-modifier-border); border-radius:10px; background:color-mix(in srgb,var(--text-normal) 4%,transparent); color:var(--text-muted); }
.qiaomu-reader-pdf-document .qiaomu-reader-pdf-zoom-control { display:grid; }
.qiaomu-reader-pdf-zoom-control button { min-width:0; height:34px; margin:0; padding:0; border:0; border-radius:0; box-shadow:none; background:transparent; color:inherit; font-family:var(--font-interface); display:flex; align-items:center; justify-content:center; cursor:pointer; }
.qiaomu-reader-pdf-zoom-control button:hover:not(:disabled) { background:var(--background-modifier-hover); color:var(--text-normal); }
.qiaomu-reader-pdf-zoom-control button:active:not(:disabled) { background:var(--background-modifier-active-hover); }
.qiaomu-reader-pdf-zoom-control button:focus-visible { position:relative; z-index:1; outline:2px solid var(--interactive-accent); outline-offset:-2px; }
.qiaomu-reader-pdf-zoom-control button:disabled { opacity:.32; cursor:default; }
.qiaomu-reader-pdf-zoom-step svg { width:15px; height:15px; }
.qiaomu-reader-pdf-zoom-control .qiaomu-reader-pdf-zoom-value { border-right:1px solid var(--background-modifier-border); border-left:1px solid var(--background-modifier-border); font-size:11px; font-weight:600; font-variant-numeric:tabular-nums; }
.qiaomu-reader-area { flex:1; overflow:hidden; position:relative; min-height:0; display:flex; align-items:stretch; margin:0; border:0; border-radius:0; box-shadow:none; background:var(--qiaomu-reader-bg,#faf8f3); box-sizing:border-box; }
/* foliate-js renders inside a custom element that has no intrinsic size, so
   the shadow host carrying it must be stretched across the reading area. */
.qiaomu-reader-engine-host { flex:1; min-width:0; min-height:0; position:relative; overflow:hidden; background:var(--qiaomu-reader-bg,#faf8f3); }
.qiaomu-reader-engine-host > * { display:block; width:100%; height:100%; margin:0; border:0; padding:0; }
.qiaomu-reader-marea { margin:0; border:none; border-radius:0; box-shadow:none; background:transparent; }
.qiaomu-reader-clip { position:relative; overflow:hidden; flex-shrink:0; }
.qiaomu-reader-flow { overflow:hidden; }
.qiaomu-reader-flow p { margin:0 0 .85em; text-align:justify; hyphens:auto; -webkit-hyphens:auto; word-break:break-word; color:inherit; font-size:inherit; font-family:inherit; line-height:inherit; }
.qiaomu-reader-flow p:last-child { margin-bottom:0; }
.qiaomu-reader-flow h1,.qiaomu-reader-flow h2,.qiaomu-reader-flow h3,.qiaomu-reader-flow h4 { margin:1.4em 0 .5em; font-weight:700; color:inherit; line-height:1.25; }
.qiaomu-reader-flow h1 { font-size:1.5em; } .qiaomu-reader-flow h2 { font-size:1.3em; } .qiaomu-reader-flow h3 { font-size:1.15em; }
.qiaomu-reader-flow strong { font-weight:700; } .qiaomu-reader-flow em { font-style:italic; }
.qiaomu-reader-loading { flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px; color:var(--qiaomu-reader-muted,#8a8678); font-family:'Inter',system-ui,sans-serif; }
.qiaomu-reader-spin { width:36px; height:36px; border:3px solid rgba(0,0,0,.1); border-top-color:var(--qiaomu-reader-accent,#5548d9); border-radius:50%; animation:qiaomu-reader-spin .7s linear infinite; }
@keyframes qiaomu-reader-spin { to { transform:rotate(360deg); } }
.qiaomu-reader-loading-text { font-size:13px; opacity:.65; }
.qiaomu-reader-bot { position:absolute; left:0; right:0; bottom:0; width:100%; height:40px; display:grid; grid-template-columns:32px minmax(0,1fr) 32px; align-items:center; padding:4px 8px; gap:6px; box-sizing:border-box; border:0; border-top:1px solid; border-radius:0; box-shadow:none; z-index:16; pointer-events:auto; }
.qiaomu-reader-navbtn { width:36px; height:36px; padding:0; display:flex; align-items:center; justify-content:center; box-sizing:border-box; border:1px solid var(--background-modifier-border); box-shadow:none; background:color-mix(in srgb,var(--text-normal) 4%,transparent); border-radius:10px; cursor:pointer; color:var(--text-muted); opacity:.82; transition:opacity .15s,background .13s,border-color .13s,transform .1s; pointer-events:auto; flex-shrink:0; }
.qiaomu-reader-navbtn:hover { opacity:1; background:var(--background-modifier-hover); border-color:color-mix(in srgb,var(--text-muted) 35%,var(--background-modifier-border)); }
.qiaomu-reader-navbtn:active { transform:scale(.88); }
.qiaomu-reader-navbtn svg { width:20px; height:20px; }
.qiaomu-reader-bot-center { justify-self:stretch; width:auto; max-width:100%; height:32px; display:flex; flex-direction:row; align-items:center; justify-content:center; gap:6px; min-width:0; padding:0 12px; box-sizing:border-box; border:0; border-radius:10px; background:transparent; box-shadow:none; pointer-events:auto; }
.qiaomu-reader-loc { font-family:'Inter',system-ui,sans-serif; font-size:11px; color:var(--text-muted); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; text-align:center; }
.qiaomu-reader-loc-clickable { cursor:pointer; border:0; box-shadow:none; background:transparent; border-radius:5px; padding:1px 6px; transition:background .13s,color .13s; }
.qiaomu-reader-loc-clickable:hover { color:var(--text-normal); background:var(--background-modifier-hover); }
.qiaomu-reader-gotopage-input { width:100%; box-sizing:border-box; margin:2px 0 14px; padding:8px 10px; font-size:15px; border:1px solid var(--background-modifier-border); border-radius:8px; background:var(--background-primary); color:var(--text-normal); }
.qiaomu-reader-pct { font-family:'Inter',system-ui,sans-serif; font-size:14px; font-weight:700; color:var(--text-accent); }
.qiaomu-reader-pct::before { content:"·"; margin-right:6px; color:var(--text-muted); font-weight:500; }
/* White chrome stays distinct from the selected page paper. */
.qiaomu-reader-top, .qiaomu-reader-bot { background:var(--qiaomu-reader-ui,var(--background-secondary)); border-color:var(--qiaomu-reader-border,var(--background-modifier-border)); color:var(--qiaomu-reader-text,var(--text-normal)); }
.qiaomu-reader-top .qiaomu-reader-ibtn, .qiaomu-reader-bot .qiaomu-reader-ibtn, .qiaomu-reader-bot .qiaomu-reader-navbtn { width:32px; height:32px; border-color:transparent; border-radius:6px; background:transparent; color:var(--qiaomu-reader-muted,var(--text-muted)); opacity:1; }
.qiaomu-reader-top .qiaomu-reader-ibtn:hover, .qiaomu-reader-bot .qiaomu-reader-ibtn:hover, .qiaomu-reader-bot .qiaomu-reader-navbtn:hover, .qiaomu-reader-bot .qiaomu-reader-loc:hover { background:color-mix(in srgb,var(--qiaomu-reader-text,var(--text-normal)) 8%,transparent); color:var(--qiaomu-reader-text,var(--text-normal)); }
.qiaomu-reader-bot .qiaomu-reader-loc { background:transparent; box-shadow:none; border:0; }
.qiaomu-reader-bot .qiaomu-reader-loc, .qiaomu-reader-bot .qiaomu-reader-pct { color:#666; font-weight:500; }


/* ── Slide-over panel: appearance, TOC, history, actions ─────────────────── */
.qiaomu-reader-overlay { position:absolute; inset:0; background:rgba(0,0,0,.35); z-index:30; opacity:0; pointer-events:none; transition:opacity .2s; backdrop-filter:blur(3px); }
.qiaomu-reader-overlay.qiaomu-reader-overlay-on { opacity:1; pointer-events:all; }
.qiaomu-reader-panel { position:absolute; top:0; right:0; bottom:0; width:300px; background:var(--qiaomu-reader-ui); border-left:1px solid var(--qiaomu-reader-border); z-index:40; overflow-y:auto; display:none; flex-direction:column; }
.qiaomu-reader-panel::-webkit-scrollbar { width:3px; }
.qiaomu-reader-panel::-webkit-scrollbar-thumb { background:var(--qiaomu-reader-border); border-radius:2px; }
.qiaomu-reader-panel.qiaomu-reader-panel-open { display:flex; animation:qiaomu-reader-panel-slide-in .22s cubic-bezier(.4,0,.2,1); box-shadow:-10px 0 40px rgba(0,0,0,.15); }
@keyframes qiaomu-reader-panel-slide-in { from { transform:translateX(calc(100% + 1px)); } to { transform:translateX(0); } }
.qiaomu-reader-toc-panel { width:280px; }
.qiaomu-reader-pan-title { padding:18px 18px 12px; font-family:'Inter',system-ui,sans-serif; font-size:10px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:var(--qiaomu-reader-muted); border-bottom:1px solid var(--qiaomu-reader-border); margin-bottom:4px; flex-shrink:0; background:var(--qiaomu-reader-ui); position:sticky; top:0; z-index:1; }
.qiaomu-reader-pan-sec { font-family:'Inter',system-ui,sans-serif; font-size:10px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:var(--qiaomu-reader-muted); opacity:.65; padding:14px 16px 7px; }
.qiaomu-reader-theme-row { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:7px; padding:0 14px 4px; }
.qiaomu-reader-theme-btn { min-width:0; padding:10px 4px; border-radius:8px; text-align:center; font-family:'Inter',system-ui,sans-serif; font-size:11px; font-weight:600; cursor:pointer; border:2px solid transparent; transition:border-color .15s,transform .1s; }
.qiaomu-reader-theme-btn:active { transform:scale(.93); }
.qiaomu-reader-theme-auto  { background:var(--background-primary); color:var(--text-normal); box-shadow:inset 0 0 0 1px var(--background-modifier-border); }
.qiaomu-reader-theme-paper { background:#f8f6f0; color:#24231f; box-shadow:inset 0 0 0 1px #dcd5c8; }
.qiaomu-reader-theme-warm { background:#f3ebdd; color:#30291f; box-shadow:inset 0 0 0 1px #d5c5ab; }
.qiaomu-reader-theme-celadon { background:#eaf0e8; color:#243029; box-shadow:inset 0 0 0 1px #c6d3c4; }
.qiaomu-reader-theme-moon { background:#eef2f3; color:#263238; box-shadow:inset 0 0 0 1px #c9d2d5; }
.qiaomu-reader-theme-night { background:#181a1b; color:#d9d7d1; box-shadow:inset 0 0 0 1px #383c3d; }
.qiaomu-reader-theme-btn.active { border-color:var(--qiaomu-reader-accent); box-shadow:0 0 0 1px var(--qiaomu-reader-accent); }
.qiaomu-reader-sz-row { display:flex; align-items:center; gap:8px; padding:0 14px 4px; }
.qiaomu-reader-sz-label { flex:1; text-align:center; font-size:14px; font-weight:700; color:var(--qiaomu-reader-text); font-family:'Inter',system-ui,sans-serif; }
.qiaomu-reader-sz-btn { padding:9px 15px; border-radius:8px; background:rgba(0,0,0,.06); border:1px solid var(--qiaomu-reader-border); font-size:13px; font-weight:700; color:var(--qiaomu-reader-text); cursor:pointer; font-family:'Inter',system-ui,sans-serif; transition:background .13s,transform .1s; user-select:none; }
.qiaomu-reader-sz-btn:hover { background:rgba(0,0,0,.11); }
.qiaomu-reader-sz-btn:active { transform:scale(.9); }
.qiaomu-reader-ff-row { display:grid; grid-template-columns:1fr 1fr 1fr; gap:7px; padding:0 14px 4px; }
.qiaomu-reader-ff-btn { padding:10px 4px; border-radius:8px; background:rgba(0,0,0,.04); border:2px solid transparent; font-size:12px; color:var(--qiaomu-reader-text); text-align:center; cursor:pointer; transition:border-color .15s,background .13s,transform .1s; }
.qiaomu-reader-ff-btn:hover { background:rgba(0,0,0,.08); }
.qiaomu-reader-ff-btn:active { transform:scale(.94); }
.qiaomu-reader-ff-btn.active { border-color:var(--qiaomu-reader-accent); background:color-mix(in srgb,var(--qiaomu-reader-accent) 10%,transparent); color:var(--qiaomu-reader-accent); }
.qiaomu-reader-lh-row { display:flex; gap:7px; padding:0 14px 4px; flex-wrap:wrap; }
.qiaomu-reader-lh-btn { padding:8px 14px; border-radius:8px; background:rgba(0,0,0,.04); border:2px solid transparent; font-family:'Inter',system-ui,sans-serif; font-size:12px; font-weight:600; color:var(--qiaomu-reader-text); cursor:pointer; transition:border-color .15s,background .13s,transform .1s; }
.qiaomu-reader-lh-btn:hover { background:rgba(0,0,0,.08); }
.qiaomu-reader-lh-btn:active { transform:scale(.92); }
.qiaomu-reader-lh-btn.active { border-color:var(--qiaomu-reader-accent); background:color-mix(in srgb,var(--qiaomu-reader-accent) 10%,transparent); color:var(--qiaomu-reader-accent); }
.qiaomu-reader-col-row { display:flex; gap:7px; padding:0 14px 18px; }
.qiaomu-reader-col-btn { flex:1; padding:11px 4px; border-radius:8px; text-align:center; font-family:'Inter',system-ui,sans-serif; font-size:12px; font-weight:600; color:var(--qiaomu-reader-text); cursor:pointer; background:rgba(0,0,0,.04); border:2px solid transparent; transition:border-color .15s,background .13s,transform .1s; }
.qiaomu-reader-col-btn:hover { background:rgba(0,0,0,.08); }
.qiaomu-reader-col-btn:active { transform:scale(.93); }
.qiaomu-reader-col-btn.active { border-color:var(--qiaomu-reader-accent); background:color-mix(in srgb,var(--qiaomu-reader-accent) 10%,transparent); color:var(--qiaomu-reader-accent); }
.qiaomu-reader-toc-list { display:flex; flex-direction:column; padding-bottom:40px; }
.qiaomu-reader-toc-item { padding:12px 18px; font-family:'Inter',system-ui,sans-serif; font-size:13px; color:var(--qiaomu-reader-text); opacity:.75; cursor:pointer; border-bottom:1px solid rgba(0,0,0,.05); line-height:1.5; transition:background .13s,opacity .13s; }
.qiaomu-reader-toc-item:hover { background:rgba(0,0,0,.04); opacity:1; }
.qiaomu-reader-toc-item.active { color:var(--qiaomu-reader-accent); opacity:1; font-weight:600; }
.qiaomu-reader-toc-empty { padding:48px 20px; text-align:center; font-family:'Inter',system-ui,sans-serif; font-size:13px; color:var(--qiaomu-reader-muted); opacity:.7; }

/* ── Library: modal shell, header, grid, cards ───────────────────────────── */
