/* ── Highlights and the selection popup ──────────────────────────────────── */
.qiaomu-reader-hl { border-radius:3px; padding:.05em 0; box-decoration-break:clone; -webkit-box-decoration-break:clone; cursor:pointer; transition:filter .12s; }
.qiaomu-reader-hl:hover { filter:brightness(.92); }
.qiaomu-reader-hl-flash { animation:qiaomu-reader-hl-flash 1.2s ease; }
@keyframes qiaomu-reader-hl-flash { 0%,100%{ box-shadow:none; } 30%{ box-shadow:0 0 0 3px var(--qiaomu-reader-accent); } }
.qiaomu-reader-hl-popup { position:absolute; z-index:35; display:flex; flex-direction:column; align-items:stretch; gap:0; padding:7px 9px; border-radius:14px; background:var(--qiaomu-reader-ui); border:1px solid var(--qiaomu-reader-border); box-shadow:0 10px 32px rgba(0,0,0,.25); opacity:0; transform:translateY(4px) scale(.96); pointer-events:none; transition:opacity .13s,transform .13s,width .16s ease; }
.qiaomu-reader-hl-popup.qiaomu-reader-hl-popup-on { opacity:1; transform:translateY(0) scale(1); pointer-events:all; }
.qiaomu-reader-hl-actions { display:flex; align-items:center; justify-content:center; gap:6px; }
/* Docked popup must clear the bottom bar (the bar is ~50px tall plus its
   safe-area); an 18px offset put it right on top of the page-turn arrows and
   the % readout. */
.qiaomu-reader-hl-popup.qiaomu-reader-hl-popup-docked { right:auto; transform:translateY(6px) scale(.96); max-width:calc(100% - 16px); flex-wrap:wrap; justify-content:center; }
.qiaomu-reader-hl-popup.qiaomu-reader-hl-popup-docked.qiaomu-reader-hl-popup-on { transform:translateY(0) scale(1); }
.qiaomu-reader-hl-sw { appearance:none; padding:0; width:28px; height:28px; border-radius:50%; cursor:pointer; border:2px solid rgba(0,0,0,.12); transition:transform .1s,background-color .12s; display:flex; align-items:center; justify-content:center; }
.qiaomu-reader-hl-sw:hover { transform:scale(1.14); }
.qiaomu-reader-hl-sw:active { transform:scale(.9); }
/* One shared look for every action button of the selection popup. Earlier
   revisions gave them three costumes — grey copy/export, an accent-tinted pill
   for bookmark/note, nothing at all for comment/translate — and the row read
   as clutter. Inside this popup colour now means "highlight colour" and
   nothing else.
   Every action belongs in this rule's selector list. An unlisted button does
   not fall back to something neutral: it keeps the .qiaomu-reader-hl-sw look,
   an unfilled ring sized for a colour chip rather than an icon — which is
   precisely what happened when the quote-copy and AI buttons were added late.
   tools-render-test.cjs compares this list against the source. */
@media (pointer: coarse) { .qiaomu-reader-hl-menu { background: var(--interactive-accent); color: var(--text-on-accent); opacity: 1; } .qiaomu-reader-hl-menu svg { color: var(--text-on-accent); } }
.qiaomu-reader-hl-copy, .qiaomu-reader-hl-comment-btn, .qiaomu-reader-hl-note, .qiaomu-reader-hl-ai, .qiaomu-reader-hl-menu { background: color-mix(in srgb, var(--qiaomu-reader-text) 6%, transparent); color: var(--qiaomu-reader-text); border-color: transparent; opacity: .62; }
.qiaomu-reader-hl-copy:hover, .qiaomu-reader-hl-comment-btn:hover, .qiaomu-reader-hl-note:hover, .qiaomu-reader-hl-ai:hover, .qiaomu-reader-hl-menu:hover { opacity: 1; background: color-mix(in srgb, var(--qiaomu-reader-text) 12%, transparent); }
.qiaomu-reader-hl-copy svg, .qiaomu-reader-hl-comment-btn svg, .qiaomu-reader-hl-note svg, .qiaomu-reader-hl-ai svg, .qiaomu-reader-hl-menu svg { width: 15px; height: 15px; stroke-width: 1.9; }
.qiaomu-reader-hl-copy { margin-left: 10px; }
.qiaomu-reader-hl-popup-commenting .qiaomu-reader-hl-actions { display:none; }
.qiaomu-reader-hl-comment-editor { width: 320px; max-width: min(320px, calc(100vw - 38px)); display:flex; flex-direction:column; gap:9px; }
.qiaomu-reader-hl-comment-quote { display:-webkit-box; overflow:hidden; -webkit-box-orient:vertical; -webkit-line-clamp:3; padding:8px 10px; border-radius:9px; background:color-mix(in srgb,var(--qiaomu-reader-text) 5%,transparent); color:var(--qiaomu-reader-muted); font-size:12px; line-height:1.5; cursor:pointer; white-space:normal; overflow-wrap:anywhere; }
.qiaomu-reader-hl-comment-quote:hover { color:var(--qiaomu-reader-text); background:color-mix(in srgb,var(--qiaomu-reader-text) 8%,transparent); }
.qiaomu-reader-hl-comment-quote.qiaomu-reader-hl-comment-quote-open { display:block; max-height:148px; overflow:auto; }
.qiaomu-reader-hl-comment-quote:focus-visible { outline:2px solid var(--qiaomu-reader-accent); outline-offset:1px; }
.qiaomu-reader-hl-comment-quote::before { content:"“"; color:var(--qiaomu-reader-accent); font-weight:700; margin-right:2px; }
.qiaomu-reader-hl-comment-quote::after { content:"”"; color:var(--qiaomu-reader-accent); font-weight:700; margin-left:2px; }
.qiaomu-reader-hl-comment-textarea { display:block; width:100%; min-height:72px; max-height:132px; resize:vertical; box-sizing:border-box; padding:9px 10px; border-radius:9px; border:1px solid var(--qiaomu-reader-border); background:var(--qiaomu-reader-bg); color:var(--qiaomu-reader-text); font:inherit; font-size:13px; line-height:1.45; }
.qiaomu-reader-hl-comment-textarea:focus { outline:2px solid color-mix(in srgb, var(--qiaomu-reader-accent) 48%, transparent); outline-offset:1px; border-color:var(--qiaomu-reader-accent); }
.qiaomu-reader-hl-comment-actions { display:flex; justify-content:flex-end; gap:7px; }
.qiaomu-reader-hl-comment-actions button { min-height:30px; padding:4px 10px; border-radius:8px; border:1px solid var(--qiaomu-reader-border); font-size:12px; cursor:pointer; }
.qiaomu-reader-hl-comment-cancel { background:transparent; color:var(--qiaomu-reader-muted); }
.qiaomu-reader-hl-comment-save { background:var(--qiaomu-reader-accent); border-color:var(--qiaomu-reader-accent); color:white; font-weight:600; }

/* ── Confirm dialog and the saved-highlights list ────────────────────────── */
.qiaomu-reader-confirm-modal .qiaomu-reader-confirm-title { font-size:1.05em; font-weight:700; margin-bottom:8px; }
.qiaomu-reader-confirm-modal .qiaomu-reader-confirm-body { opacity:.85; line-height:1.5; margin-bottom:18px; }
.qiaomu-reader-confirm-modal .qiaomu-reader-confirm-btns { display:flex; justify-content:flex-end; gap:10px; }
.qiaomu-reader-confirm-modal .qiaomu-reader-confirm-yes { background:var(--interactive-accent); color:var(--text-on-accent); font-weight:600; }
.qiaomu-reader-confirm-modal .qiaomu-reader-confirm-no { background:var(--background-modifier-border); }
.qiaomu-reader-hl-item { display:flex; align-items:flex-start; gap:10px; padding:12px 14px 12px 16px; border-bottom:1px solid rgba(0,0,0,.05); cursor:pointer; transition:background .13s; }
.qiaomu-reader-hl-item:hover { background:rgba(0,0,0,.04); }
.qiaomu-reader-hl-dot { width:10px; height:10px; border-radius:50%; margin-top:5px; flex-shrink:0; box-shadow:0 0 0 1px rgba(0,0,0,.1); }
.qiaomu-reader-hl-body { flex:1; min-width:0; display:flex; flex-direction:column; }
.qiaomu-reader-hl-text { font-family:'Inter',system-ui,sans-serif; font-size:12.5px; line-height:1.5; color:var(--qiaomu-reader-text); opacity:.85; overflow-wrap:anywhere; }
.qiaomu-reader-hl-del { flex-shrink:0; width:24px; height:24px; display:flex; align-items:center; justify-content:center; border-radius:6px; color:var(--qiaomu-reader-muted); opacity:.5; transition:opacity .13s,color .13s,background .13s; }
.qiaomu-reader-hl-del:hover { opacity:1; color:#e5484d; background:rgba(0,0,0,.06); }
.qiaomu-reader-hl-del svg { width:15px; height:15px; }
.qiaomu-reader-hl-more { flex-shrink:0; width:24px; height:24px; display:flex; align-items:center; justify-content:center; border-radius:6px; color:var(--qiaomu-reader-muted); opacity:.5; transition:opacity .13s,color .13s,background .13s; }
.qiaomu-reader-hl-more:hover { opacity:1; color:var(--qiaomu-reader-text); background:rgba(0,0,0,.06); }
.qiaomu-reader-hl-more svg { width:16px; height:16px; }
.qiaomu-reader-toc-empty { white-space:pre-line; }
.qiaomu-reader-hist-row { display:flex; flex-direction:column; gap:6px; padding:0 14px 18px; }
.qiaomu-reader-hist-chip { padding:9px 12px; border-radius:8px; background:rgba(0,0,0,.04); border:1px solid var(--qiaomu-reader-border); font-family:'Inter',system-ui,sans-serif; font-size:12px; font-weight:600; color:var(--qiaomu-reader-text); cursor:pointer; transition:background .13s,border-color .13s,transform .1s; }
.qiaomu-reader-hist-chip:hover { background:color-mix(in srgb,var(--qiaomu-reader-accent) 10%,transparent); border-color:var(--qiaomu-reader-accent); color:var(--qiaomu-reader-accent); }
.qiaomu-reader-hist-chip:active { transform:scale(.97); }
.qiaomu-reader-hist-empty { padding:6px 14px 16px; font-family:'Inter',system-ui,sans-serif; font-size:12px; color:var(--qiaomu-reader-muted); opacity:.7; }
.qiaomu-reader-act-row { display:flex; flex-direction:column; gap:7px; padding:0 14px 22px; }
.qiaomu-reader-act-btn { display:flex; align-items:center; gap:10px; padding:10px 13px; border-radius:9px; background:rgba(0,0,0,.04); border:1px solid var(--qiaomu-reader-border); font-family:'Inter',system-ui,sans-serif; font-size:13px; font-weight:600; color:var(--qiaomu-reader-text); cursor:pointer; transition:background .13s,border-color .13s,transform .1s; }
.qiaomu-reader-act-btn:hover { background:color-mix(in srgb,var(--qiaomu-reader-accent) 10%,transparent); border-color:var(--qiaomu-reader-accent); color:var(--qiaomu-reader-accent); }
.qiaomu-reader-act-btn:active { transform:scale(.98); }
.qiaomu-reader-act-btn svg { width:16px; height:16px; flex-shrink:0; }
.qiaomu-reader-hist-manual { border-color:color-mix(in srgb,var(--qiaomu-reader-accent) 55%,transparent); background:color-mix(in srgb,var(--qiaomu-reader-accent) 8%,transparent); }
.qiaomu-reader-hl-export { display:flex; align-items:center; justify-content:center; gap:8px; margin:10px 14px 4px; padding:10px 12px; border-radius:9px; background:color-mix(in srgb,var(--qiaomu-reader-accent) 12%,transparent); border:1px solid color-mix(in srgb,var(--qiaomu-reader-accent) 35%,transparent); color:var(--qiaomu-reader-accent); font-family:'Inter',system-ui,sans-serif; font-size:12.5px; font-weight:600; cursor:pointer; transition:background .13s,border-color .13s,transform .1s; }
.qiaomu-reader-hl-export:hover { background:color-mix(in srgb,var(--qiaomu-reader-accent) 20%,transparent); border-color:var(--qiaomu-reader-accent); }
.qiaomu-reader-hl-export:active { transform:scale(.98); }
.qiaomu-reader-hl-export svg { width:16px; height:16px; }

/* ── Settings-page callouts, store recovery, ACP guide ───────────────────── */
.qiaomu-reader-set-note { font-size:12.5px; line-height:1.6; color:var(--text-muted); background:var(--background-secondary); border:1px solid var(--background-modifier-border); border-radius:9px; padding:11px 13px; margin:6px 0 14px; }
.qiaomu-reader-set-note code { font-size:11.5px; background:var(--background-modifier-hover); padding:1px 5px; border-radius:4px; word-break:break-all; }
.qiaomu-reader-store-recovery { margin:10px 0 18px; padding:13px 14px; border:1px solid color-mix(in srgb,var(--text-warning,#d98a00) 45%,var(--background-modifier-border)); border-radius:10px; background:color-mix(in srgb,var(--text-warning,#d98a00) 7%,var(--background-secondary)); }
.qiaomu-reader-store-recovery-title { display:flex; align-items:center; gap:8px; color:var(--text-normal); font-size:13.5px; font-weight:700; }
.qiaomu-reader-store-recovery-icon { display:inline-flex; color:var(--text-warning,#b87300); }
.qiaomu-reader-store-recovery-icon svg { width:16px; height:16px; }
.qiaomu-reader-store-recovery-copy { margin:7px 0 9px; color:var(--text-muted); font-size:12.5px; line-height:1.55; }
.qiaomu-reader-store-recovery-path { display:flex; align-items:baseline; gap:5px; margin-top:5px; color:var(--text-muted); font-size:12px; }
.qiaomu-reader-store-recovery-path code { min-width:0; padding:2px 5px; border-radius:4px; background:var(--background-primary); color:var(--text-normal); font-size:11.5px; overflow-wrap:anywhere; }
.qiaomu-reader-store-recovery-actions { display:flex; justify-content:flex-end; gap:8px; margin-top:12px; }
@media (max-width:500px) { .qiaomu-reader-store-recovery-path { display:block; } .qiaomu-reader-store-recovery-path code { display:block; margin-top:3px; } .qiaomu-reader-store-recovery-actions { align-items:stretch; flex-direction:column; } }
/* ACP onboarding: one compact explanation, then the provider-specific step. */
.qiaomu-reader-acp-guide { margin:10px 0 14px; padding:12px 13px; border:1px solid color-mix(in srgb,var(--interactive-accent) 24%,var(--background-modifier-border)); border-radius:10px; background:color-mix(in srgb,var(--interactive-accent) 5%,var(--background-secondary)); }
.qiaomu-reader-acp-guide-heading { display:flex; align-items:center; gap:7px; color:var(--text-normal); font-size:13px; font-weight:700; }
.qiaomu-reader-acp-guide-icon { display:inline-flex; color:var(--interactive-accent); }
.qiaomu-reader-acp-guide-icon svg { width:15px; height:15px; }
.qiaomu-reader-acp-guide-copy { margin-top:5px; color:var(--text-muted); font-size:12.5px; line-height:1.55; }
.qiaomu-reader-acp-install { display:flex; flex-direction:column; align-items:flex-start; gap:7px; margin-top:10px; padding-top:10px; border-top:1px solid var(--background-modifier-border); }
.qiaomu-reader-acp-guide-badge { display:inline-flex; align-items:center; min-height:22px; padding:2px 8px; border-radius:999px; background:color-mix(in srgb,var(--interactive-accent) 13%,transparent); color:var(--interactive-accent); font-size:11.5px; font-weight:650; }
.qiaomu-reader-acp-guide-badge.is-community { background:color-mix(in srgb,var(--text-warning,#d98a00) 13%,transparent); color:var(--text-warning,#b87300); }
.qiaomu-reader-acp-install-note { color:var(--text-muted); font-size:12.5px; line-height:1.5; }
.qiaomu-reader-acp-install-command { display:flex; align-items:center; gap:8px; width:100%; min-width:0; }
.qiaomu-reader-acp-install-command code { flex:1 1 auto; min-width:0; overflow-x:auto; padding:7px 9px; border-radius:6px; background:var(--background-primary); color:var(--text-normal); font-size:11.5px; line-height:1.4; white-space:nowrap; }
.qiaomu-reader-acp-install-command button { flex:0 0 auto; min-height:30px; padding:4px 10px; font-size:11.5px; }
@media (max-width:500px) { .qiaomu-reader-acp-install-command { align-items:stretch; flex-direction:column; } .qiaomu-reader-acp-install-command code { width:100%; } }

/* ── Info modal and onboarding ───────────────────────────────────────────── */
.qiaomu-reader-info-modal { max-width:560px; }
.qiaomu-reader-info-title { font-size:19px; font-weight:700; color:var(--text-normal); }
.qiaomu-reader-info-sub { font-size:13px; color:var(--text-muted); margin:2px 0 16px; }
.qiaomu-reader-info-group { font-size:10.5px; font-weight:700; letter-spacing:.09em; text-transform:uppercase; color:var(--text-muted); opacity:.8; margin:18px 0 8px; }
.qiaomu-reader-info-row { display:flex; gap:12px; align-items:flex-start; padding:9px 0; border-top:1px solid var(--background-modifier-border); }
.qiaomu-reader-info-ic { flex-shrink:0; width:34px; height:34px; display:flex; align-items:center; justify-content:center; border-radius:8px; background:var(--background-modifier-hover); color:var(--text-normal); }
.qiaomu-reader-info-ic svg { width:18px; height:18px; }
.qiaomu-reader-info-tx { flex:1; min-width:0; }
.qiaomu-reader-info-rowtitle { font-size:13.5px; font-weight:600; color:var(--text-normal); }
.qiaomu-reader-info-rowdesc { font-size:12.5px; line-height:1.5; color:var(--text-muted); margin-top:2px; }
.qiaomu-reader-info-note { margin-top:20px; padding:13px 15px; border-radius:10px; background:var(--background-modifier-hover); }

.qiaomu-reader-onb-modal { max-width:480px; }
.qiaomu-reader-onb-card { text-align:center; padding:8px 6px 4px; min-height:300px; display:flex; flex-direction:column; }
.qiaomu-reader-onb-card.qiaomu-reader-onb-warn .qiaomu-reader-onb-emoji { filter:drop-shadow(0 2px 8px rgba(255,170,40,.35)); }
.qiaomu-reader-onb-emoji { font-size:52px; line-height:1; margin:10px 0 14px; }
.qiaomu-reader-onb-title { font-size:20px; font-weight:800; color:var(--text-normal); margin-bottom:14px; }
.qiaomu-reader-onb-card.qiaomu-reader-onb-warn .qiaomu-reader-onb-title { color:var(--text-warning, #d98a00); }
.qiaomu-reader-onb-body { text-align:left; }
.qiaomu-reader-onb-body p { font-size:13.5px; line-height:1.6; color:var(--text-muted); margin:0 0 11px; }
.qiaomu-reader-onb-card.qiaomu-reader-onb-warn .qiaomu-reader-onb-body { background:color-mix(in srgb,var(--text-warning,#e0a020) 12%,transparent); border-radius:10px; padding:13px 15px; }
.qiaomu-reader-onb-dots { display:flex; justify-content:center; gap:7px; margin:16px 0 4px; }
.qiaomu-reader-onb-dot { width:8px; height:8px; border-radius:50%; background:var(--background-modifier-border); cursor:pointer; transition:transform .12s,background .12s; }
.qiaomu-reader-onb-dot:hover { transform:scale(1.25); }
.qiaomu-reader-onb-dot-on { background:var(--interactive-accent); transform:scale(1.15); }
.qiaomu-reader-onb-nav { display:flex; align-items:center; justify-content:space-between; gap:10px; margin-top:14px; }
.qiaomu-reader-onb-counter { font-size:12px; color:var(--text-muted); font-variant-numeric:tabular-nums; }
.qiaomu-reader-onb-nav button { cursor:pointer; }
.qiaomu-reader-onb-prev:disabled { opacity:.4; cursor:default; }
.qiaomu-reader-onb-start { background:var(--interactive-accent); color:var(--text-on-accent); font-weight:700; }
.qiaomu-reader-onb-skip { text-align:center; margin-top:12px; min-height:18px; font-size:12px; color:var(--text-faint); cursor:pointer; user-select:none; }
.qiaomu-reader-onb-skip:hover { color:var(--text-muted); text-decoration:underline; }

.qiaomu-reader-onb-anim { animation:qiaomu-reader-onb-in .26s cubic-bezier(.22,.61,.36,1) both; }
@keyframes qiaomu-reader-onb-in { from { opacity:0; transform:translateY(6px) scale(.992); } to { opacity:1; transform:none; } }
@media (prefers-reduced-motion:reduce) { .qiaomu-reader-onb-anim { animation:none; } }

.qiaomu-reader-onb-modal .modal-content { position:relative; }
.qiaomu-reader-lang-switch { position:absolute; top:12px; left:14px; z-index:5; display:inline-flex; padding:2px; gap:2px; border-radius:999px; background:var(--background-modifier-hover); box-shadow:inset 0 0 0 1px var(--background-modifier-border); }
/* These segments are <button>s, and app/theme button styles outrank a single
   class — so every visual property is re-declared under .qiaomu-reader-lang-switch
   and forced; otherwise the active segment renders as a white button with white
   text (invisible — exactly what appeared on screen 137). */
.qiaomu-reader-lang-switch .qiaomu-reader-lang-opt { box-sizing:border-box; cursor:pointer; margin:0; padding:3px 11px; border:none; border-radius:999px; font-size:11px; font-weight:700; letter-spacing:.03em; line-height:1.5; box-shadow:none; background:transparent; color:var(--text-muted); transition:color .15s ease, background .15s ease; }
.qiaomu-reader-lang-switch .qiaomu-reader-lang-opt:hover { color:var(--text-normal); background:transparent; }
.qiaomu-reader-lang-switch .qiaomu-reader-lang-opt.qiaomu-reader-lang-on { background:var(--interactive-accent); color:var(--text-on-accent); box-shadow:0 1px 3px rgba(0,0,0,.2); }

/* ── Daily goal bar and reading timer ────────────────────────────────────── */
.qiaomu-reader-goalbar { position:relative; flex-shrink:0; height:22px; margin:0 16px 9px; border-radius:8px; overflow:hidden; display:flex; align-items:center; justify-content:center; background:color-mix(in srgb,var(--qiaomu-reader-text,#1a1a2e) 8%,transparent); box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--qiaomu-reader-text,#1a1a2e) 6%,transparent); transition:opacity .5s ease; }
.qiaomu-reader-marea + .qiaomu-reader-goalbar { margin:0 12px 7px; }
.qiaomu-reader-goal-fill { position:absolute; left:0; top:0; bottom:0; width:0%; background:linear-gradient(90deg,color-mix(in srgb,var(--qiaomu-reader-accent) 60%,transparent),color-mix(in srgb,var(--qiaomu-reader-accent) 20%,transparent)); transition:width .55s cubic-bezier(.4,0,.2,1); }
.qiaomu-reader-goal-txt { position:relative; z-index:1; font-family:'Inter',system-ui,sans-serif; font-size:11px; font-weight:700; letter-spacing:.015em; color:var(--qiaomu-reader-text); opacity:.72; white-space:nowrap; pointer-events:none; }
.qiaomu-reader-goal-done .qiaomu-reader-goal-fill { background:linear-gradient(90deg,rgba(76,175,110,.55),rgba(76,175,110,.26)); }
.qiaomu-reader-goal-done .qiaomu-reader-goal-txt { color:color-mix(in srgb,#3ea564 78%,var(--qiaomu-reader-text)); opacity:1; }
@media (max-width:600px) { .qiaomu-reader-goalbar { height:24px; } }

.qiaomu-reader-timerbtn { display:flex; align-items:center; gap:5px; height:36px; padding:0 10px; margin:0; box-sizing:border-box; border-radius:10px; cursor:pointer; color:var(--qiaomu-reader-text); background:color-mix(in srgb,var(--qiaomu-reader-text,#1a1a2e) 6%,transparent); border:1px solid var(--qiaomu-reader-border,#ddd9ce); box-shadow:none; opacity:.82; transition:opacity .15s,background .13s,border-color .13s,transform .1s; flex-shrink:0; user-select:none; }
.qiaomu-reader-timer-reset { display:none; align-items:center; justify-content:center; width:22px; height:22px; margin-left:2px; border-radius:5px; cursor:pointer; opacity:.5; transition:opacity .13s,background .1s; }
.qiaomu-reader-timer-reset:hover { opacity:1; background:rgba(0,0,0,.08); }
.qiaomu-reader-timer-reset:active { transform:scale(.9); }
.qiaomu-reader-timer-reset svg { width:12px; height:12px; }
.qiaomu-reader-timerbtn:hover { opacity:1; background:color-mix(in srgb,var(--qiaomu-reader-text) 11%,transparent); }
.qiaomu-reader-timerbtn:active { transform:scale(.94); }
.qiaomu-reader-timer-ic { display:flex; align-items:center; }
.qiaomu-reader-timer-ic svg { width:13px; height:13px; }
.qiaomu-reader-timer-label { font-family:'Inter',system-ui,sans-serif; font-size:12px; font-weight:700; letter-spacing:.02em; font-variant-numeric:tabular-nums; min-width:30px; text-align:left; }
.qiaomu-reader-timerbtn.qiaomu-reader-timer-run { color:var(--qiaomu-reader-accent); border-color:color-mix(in srgb,var(--qiaomu-reader-accent) 45%,transparent); background:color-mix(in srgb,var(--qiaomu-reader-accent) 12%,transparent); opacity:1; }
.qiaomu-reader-timerbtn.qiaomu-reader-timer-run:hover { background:color-mix(in srgb,var(--qiaomu-reader-accent) 18%,transparent); }
.qiaomu-reader-timerbtn.qiaomu-reader-timer-done { color:color-mix(in srgb,#3ea564 78%,var(--qiaomu-reader-text)); border-color:rgba(76,175,110,.45); background:rgba(76,175,110,.14); opacity:1; }
.qiaomu-reader-timerbtn.qiaomu-reader-timer-done:hover { background:rgba(76,175,110,.2); }
@media (max-width:600px) { .qiaomu-reader-timerbtn { height:44px; } }

/* ── Edge tap zones and immersive mode ───────────────────────────────────── */
.qiaomu-reader-navclick .qiaomu-reader-area::before, .qiaomu-reader-navclick .qiaomu-reader-area::after { content:""; position:absolute; top:0; bottom:0; width:16%; z-index:5; pointer-events:none; opacity:0; transition:opacity .22s ease; }
.qiaomu-reader-navclick .qiaomu-reader-area::before { left:0;  background:linear-gradient(90deg,color-mix(in srgb,var(--qiaomu-reader-accent) 14%,transparent),transparent); }
.qiaomu-reader-navclick .qiaomu-reader-area::after  { right:0; background:linear-gradient(270deg,color-mix(in srgb,var(--qiaomu-reader-accent) 14%,transparent),transparent); }
.qiaomu-reader-navclick .qiaomu-reader-area:hover::before, .qiaomu-reader-navclick .qiaomu-reader-area:hover::after { opacity:1; }

/* ── Immersive mode: chrome floats over the page, then fully retracts ────── */
.qiaomu-reader-top, .qiaomu-reader-bot { transition:opacity .22s ease-out,transform .22s cubic-bezier(.2,.8,.2,1),background .2s; }
.qiaomu-reader-immersive .qiaomu-reader-top { opacity:0; transform:translateY(calc(-100% - 16px)); pointer-events:none; }
.qiaomu-reader-immersive .qiaomu-reader-bot { opacity:0; transform:translateY(calc(100% + 16px)); pointer-events:none; }
.qiaomu-reader-immersive .qiaomu-reader-goalbar { opacity:0; pointer-events:none; }

.qiaomu-reader-pan-hint { padding:2px 16px 12px; font-family:'Inter',system-ui,sans-serif; font-size:11px; line-height:1.5; color:var(--qiaomu-reader-muted); opacity:.85; }

/* ── First-run setup modal ───────────────────────────────────────────────── */
.qiaomu-reader-setup-modal { max-width:520px; }
.qiaomu-reader-setup-lead { font-size:13px; line-height:1.55; color:var(--text-muted); margin:0 0 14px; }
.qiaomu-reader-setup-back { font-size:12.5px; color:var(--text-muted); cursor:pointer; user-select:none; margin-bottom:10px; display:inline-block; }
.qiaomu-reader-setup-back:hover { color:var(--text-normal); }
.qiaomu-reader-setup-field { margin-bottom:12px; }
.qiaomu-reader-setup-label { font-size:11px; font-weight:600; letter-spacing:.04em; text-transform:uppercase; color:var(--text-muted); margin-bottom:5px; }
.qiaomu-reader-setup-input { width:100%; box-sizing:border-box; padding:8px 10px; border-radius:7px; border:1px solid var(--background-modifier-border); background:var(--background-modifier-form-field); color:var(--text-normal); font-size:13.5px; }
.qiaomu-reader-setup-input:focus { outline:none; border-color:var(--interactive-accent); }
.qiaomu-reader-setup-list { max-height:280px; overflow-y:auto; margin:10px 0 4px; border:1px solid var(--background-modifier-border); border-radius:8px; }
.qiaomu-reader-setup-row { padding:9px 12px; cursor:pointer; border-bottom:1px solid var(--background-modifier-border); }
.qiaomu-reader-setup-row:last-child { border-bottom:none; }
.qiaomu-reader-setup-row:hover { background:var(--background-modifier-hover); }
.qiaomu-reader-setup-row-name { font-size:13.5px; color:var(--text-normal); }
.qiaomu-reader-setup-row-path { font-size:11.5px; color:var(--text-faint); margin-top:2px; }
.qiaomu-reader-setup-empty { padding:18px 12px; text-align:center; font-size:12.5px; color:var(--text-muted); }
.qiaomu-reader-setup-foot { display:flex; flex-direction:column; gap:8px; margin-top:16px; padding-top:14px; border-top:1px solid var(--background-modifier-border); }
.qiaomu-reader-setup-btn { width:100%; padding:9px 12px; border-radius:8px; font-size:13.5px; cursor:pointer; border:1px solid var(--background-modifier-border); background:var(--interactive-normal); color:var(--text-normal); transition:background .12s, border-color .12s; }
.qiaomu-reader-setup-btn:hover { background:var(--interactive-hover); }
.qiaomu-reader-setup-btn-primary { background:var(--interactive-accent); color:var(--text-on-accent); border-color:var(--interactive-accent); font-weight:600; }
.qiaomu-reader-setup-btn-primary:hover { background:var(--interactive-accent-hover); }
.qiaomu-reader-setup-btn-primary:disabled { opacity:.6; cursor:default; }
.qiaomu-reader-setup-btn-quiet { background:transparent; color:var(--text-muted); border-color:transparent; }
.qiaomu-reader-setup-btn-quiet:hover { background:var(--background-modifier-hover); }
.qiaomu-reader-setup-hint { font-size:11.5px; line-height:1.5; color:var(--text-faint); margin-top:-4px; }

/* ── Library filter chips ──────────────────────────────────────────────────
   Chips share the 30px side padding of .qiaomu-reader-lib-hdr and
   .qiaomu-reader-lib-grid so header, chips and covers share one left edge; at
   4px the first chip sat jammed against the window frame. */
.qiaomu-reader-lib-chips { display:flex; flex-wrap:wrap; gap:8px; padding:0 30px; margin:16px 0 18px; }
.qiaomu-reader-lib-chip { display:inline-flex; align-items:center; gap:7px; padding:6px 13px; border-radius:8px; font-size:12.5px; line-height:1.25; cursor:pointer; user-select:none; white-space:nowrap; color:var(--qiaomu-reader-lib-muted); background:transparent; border:1px solid var(--qiaomu-reader-lib-border); transition:color .13s, border-color .13s, background .13s; }
.qiaomu-reader-lib-chip:hover { color:var(--qiaomu-reader-lib-text); border-color:var(--qiaomu-reader-lib-muted); }
.qiaomu-reader-lib-chip-n { font-size:11px; opacity:.6; font-variant-numeric:tabular-nums; }
.qiaomu-reader-lib-chip-on { color:var(--qiaomu-reader-lib-text); font-weight:600; border-color:var(--qiaomu-reader-lib-text); background:color-mix(in srgb, var(--qiaomu-reader-lib-text) 6%, transparent); }
.qiaomu-reader-lib-chip-on .qiaomu-reader-lib-chip-n { opacity:.7; }

.qiaomu-reader-pan-adv-hdr { display:flex; align-items:center; gap:9px; cursor:pointer; user-select:none; margin:16px 14px 4px; padding:10px 12px; border-radius:9px; border:1px solid var(--qiaomu-reader-border); background:color-mix(in srgb,var(--qiaomu-reader-text) 5%,transparent); font-family:'Inter',system-ui,sans-serif; font-size:12.5px; font-weight:600; color:var(--qiaomu-reader-text); opacity:.9; transition:background .13s, opacity .13s; }
.qiaomu-reader-pan-adv-hdr:hover { opacity:1; background:color-mix(in srgb,var(--qiaomu-reader-text) 10%,transparent); }
.qiaomu-reader-pan-adv-ic { font-size:13px; line-height:1; }
.qiaomu-reader-pan-adv-lbl { flex:1; }
.qiaomu-reader-pan-adv-car { font-size:15px; line-height:1; opacity:.6; transform:rotate(0deg); transition:transform .18s ease; }
.qiaomu-reader-pan-adv-car-on { transform:rotate(90deg); }
/* grid-template-rows 0fr → 1fr animates the height without hardcoding one;
   the trick needs exactly one child, hence .qiaomu-reader-pan-adv-body. */
.qiaomu-reader-pan-adv { display:grid; grid-template-rows:0fr; transition:grid-template-rows .22s ease; }
.qiaomu-reader-pan-adv-body { overflow:hidden; }
.qiaomu-reader-pan-adv.qiaomu-reader-pan-adv-on { grid-template-rows:1fr; }

/* ── Plugin settings tab ─────────────────────────────────────────────────── */
.qiaomu-reader-settings-definition.setting-item{display:block;padding:0;border:0;background:transparent;box-shadow:none}
.qiaomu-reader-settings-root { max-width: 820px; }
.qiaomu-reader-settings-head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--size-4-4); margin: 2px 0 var(--size-4-5); }
.qiaomu-reader-settings-head-text h2 { margin: 0; font-size: 24px; letter-spacing: -.02em; }
.qiaomu-reader-settings-head-text div { margin-top: 5px; color: var(--text-muted); font-size: var(--font-ui-small); }
.qiaomu-reader-settings-language { flex: 0 0 auto; min-width: 112px; }
.qiaomu-reader-set-tabs { display:flex; gap:4px; margin:0 0 24px; padding:4px; border:1px solid var(--background-modifier-border); border-radius:12px; background:var(--background-secondary); overflow-x:auto; overflow-y:hidden; scrollbar-width:none; }
.qiaomu-reader-set-tabs::-webkit-scrollbar { display:none; }
.qiaomu-reader-set-tab { flex:1 0 auto; padding:8px 11px; font-size:13px; font-weight:600; cursor:pointer; white-space:nowrap; text-align:center; color:var(--text-muted); border-radius:8px; transition:color .13s, background .13s, box-shadow .13s; }
.qiaomu-reader-set-tab:hover { color:var(--text-normal); background:var(--background-modifier-hover); }
.qiaomu-reader-set-tab-on { color:var(--text-normal); background:var(--background-primary); box-shadow:0 1px 3px rgba(0,0,0,.10); }
.qiaomu-reader-settings-intro { margin: 0 0 20px; }
.qiaomu-reader-settings-intro h2 { margin: 0; font-size: 20px; letter-spacing: -.01em; }
.qiaomu-reader-settings-intro div { margin-top: 5px; color: var(--text-muted); font-size: var(--font-ui-small); line-height: 1.5; }
.qiaomu-reader-set-body .setting-item:first-child { border-top:none; padding-top:0; }
.qiaomu-reader-set-body .setting-item { padding-top: 14px; padding-bottom: 14px; }
.qiaomu-reader-set-body .setting-item-description { max-width: 560px; line-height: 1.5; }
.qiaomu-reader-set-body h3 { margin: 28px 0 2px; padding-bottom: 8px; border-bottom: 1px solid var(--background-modifier-border); font-size: var(--font-ui-small); font-weight: 700; letter-spacing: 0; text-transform: none; color: var(--text-normal); }
.qiaomu-reader-set-body h3:first-child { margin-top: 4px; }
.qiaomu-reader-settings-disclosure { margin-top:24px; border:1px solid var(--background-modifier-border); border-radius:12px; background:color-mix(in srgb,var(--background-secondary) 48%,transparent); overflow:hidden; }
.qiaomu-reader-settings-disclosure > summary { padding:12px 14px; cursor:pointer; font-size:var(--font-ui-small); font-weight:650; color:var(--text-normal); list-style-position:inside; }
.qiaomu-reader-settings-disclosure > summary:hover { background:var(--background-modifier-hover); }
.qiaomu-reader-settings-disclosure[open] > summary { border-bottom:1px solid var(--background-modifier-border); }
.qiaomu-reader-settings-disclosure-body { padding:2px 14px 8px; min-width:0; }
.qiaomu-reader-folder-setting .setting-item-control { display:grid; grid-template-columns:minmax(180px,1fr) 32px; align-items:center; gap:4px 6px; min-width:min(100%,320px); }
.qiaomu-reader-folder-setting .qiaomu-reader-folder-path-input, .qiaomu-reader-file-path-setting input { width:100%; min-width:0; }
.qiaomu-reader-folder-setting .clickable-icon, .qiaomu-reader-file-path-setting .clickable-icon { margin:0; }
.qiaomu-reader-folder-path-status { grid-column:1 / -1; min-width:0; color:var(--text-muted); font-size:var(--font-ui-smaller); line-height:1.4; overflow-wrap:anywhere; }
.qiaomu-reader-folder-path-status.is-error { color:var(--text-error); }
.qiaomu-reader-folder-path-input[aria-invalid="true"] { border-color:var(--text-error); box-shadow:0 0 0 1px var(--text-error); }
.qiaomu-reader-folder-create-error { min-height:0; color:var(--text-error); font-size:var(--font-ui-small); line-height:1.45; }
.qiaomu-reader-folder-create-error:not(:empty) { margin:0 0 10px; }
.qiaomu-reader-folder-create-actions { border-top:0; }
.is-mobile .qiaomu-reader-settings-head { align-items: stretch; flex-direction: column; }
.is-mobile .qiaomu-reader-settings-language { width: 100%; }
.is-mobile .qiaomu-reader-set-tabs { margin-bottom:18px; }
.is-mobile .qiaomu-reader-set-tab { flex:0 0 auto; padding:8px 12px; }
.is-mobile .qiaomu-reader-folder-setting .setting-item-control, .is-mobile .qiaomu-reader-file-path-setting .setting-item-control { width:100%; }
@media (pointer:coarse) { /* touch: roomier path controls */
  .qiaomu-reader-folder-setting .setting-item-control { grid-template-columns:minmax(0,1fr) 44px; }
  .qiaomu-reader-folder-setting .clickable-icon, .qiaomu-reader-file-path-setting .clickable-icon { min-height:44px; }
}

/* ── Panel variants of the info styles ───────────────────────────────────── */
.qiaomu-reader-panel .qiaomu-reader-info-group { font-family:'Inter',system-ui,sans-serif; font-size:10px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:var(--qiaomu-reader-muted); opacity:.65; padding:14px 16px 6px; }
.qiaomu-reader-panel .qiaomu-reader-info-booknote { padding:0 16px 4px; }
.qiaomu-reader-panel .qiaomu-reader-info-rowdesc { font-family:'Inter',system-ui,sans-serif; font-size:11px; line-height:1.5; color:var(--qiaomu-reader-muted); opacity:.85; }
.qiaomu-reader-panel .qiaomu-reader-info-booknote input:focus { outline:none; border-color:var(--qiaomu-reader-accent); }

.qiaomu-reader-pan-adv-count:empty { display:none; }
/* .qiaomu-reader-pan-adv-lbl is flex:1, so the badge already lands beside the
   caret and the header's own gap provides the spacing. */
.qiaomu-reader-pan-adv-count { padding:1px 7px; border-radius:999px; font-size:11px; font-weight:700; line-height:1.5; color:var(--qiaomu-reader-text); opacity:.6; background:color-mix(in srgb,var(--qiaomu-reader-text) 10%,transparent); }

/* ── E-ink profile: no transitions, no shadows ───────────────────────────── */
.qiaomu-reader-eink .qiaomu-reader-area { border-color: #000; border-radius: 0; }
.qiaomu-reader-eink .qiaomu-reader-relayout-spin { display: none; }
.qiaomu-reader-eink .qiaomu-reader-ibtn { min-width: 40px; min-height: 40px; }
.qiaomu-reader-eink .qiaomu-reader-hist-chip, .qiaomu-reader-eink .qiaomu-reader-lib-chip { border-radius: 0; }

/* ── Export list ─────────────────────────────────────────────────────────── */
.qiaomu-reader-exp-bar { display:flex; align-items:center; gap:14px; flex-wrap:wrap; margin:14px 0 8px; font-size:12px; }
.qiaomu-reader-exp-count { color:var(--text-muted); margin-right:auto; font-variant-numeric:tabular-nums; }
.qiaomu-reader-exp-link { color:var(--text-accent); cursor:pointer; }
.qiaomu-reader-exp-link:hover { text-decoration:underline; }
.qiaomu-reader-exp-list { max-height:min(420px, 52vh); overflow-y:auto; border:1px solid var(--background-modifier-border); border-radius:8px; }
.qiaomu-reader-exp-row { display:flex; gap:10px; padding:10px 12px; cursor:pointer; border-bottom:1px solid var(--background-modifier-border); }
.qiaomu-reader-exp-row:last-child { border-bottom:none; }
.qiaomu-reader-exp-row:hover { background:var(--background-modifier-hover); }
.qiaomu-reader-exp-box { margin-top:3px; flex:none; }
.qiaomu-reader-exp-body { min-width:0; }
.qiaomu-reader-exp-text { font-size:13px; line-height:1.5; color:var(--text-normal); }
.qiaomu-reader-exp-done .qiaomu-reader-exp-text { opacity:.55; }
.qiaomu-reader-exp-tag { margin-top:4px; font-size:11px; color:var(--text-muted); }

/* ── Title-modal hint and relayout feedback ──────────────────────────────── */
.qiaomu-reader-title-modal .qiaomu-reader-setup-field { margin-top: 14px; }
.qiaomu-reader-title-alt { margin-top: 8px; font-size: 12px; cursor: pointer; color: var(--text-accent); opacity: .85; width: fit-content; }
.qiaomu-reader-title-alt:hover { opacity: 1; text-decoration: underline; }

.qiaomu-reader-view { position: relative; }
.qiaomu-reader-area { transition: filter .18s ease, opacity .18s ease; }
.qiaomu-reader-relayouting .qiaomu-reader-area { filter: blur(7px); opacity: .45; }

.qiaomu-reader-relayout-spin { position: absolute; inset: 0; z-index: 5; display: flex; align-items: center; justify-content: center; opacity: 0; pointer-events: none; transition: opacity .18s ease; }
.qiaomu-reader-relayouting .qiaomu-reader-relayout-spin { opacity: 1; }
.qiaomu-reader-relayout-ring { width: 30px; height: 30px; border-radius: 50%; border: 2.5px solid color-mix(in srgb, var(--qiaomu-reader-text) 18%, transparent); border-top-color: var(--qiaomu-reader-accent); animation: qiaomu-reader-relayout-turn .7s linear infinite; }
@keyframes qiaomu-reader-relayout-turn { to { transform: rotate(360deg); } }

@media (prefers-reduced-motion: reduce) { /* reduced motion: calm the relayout feedback */
  .qiaomu-reader-relayouting .qiaomu-reader-area { filter: blur(8px); opacity: .4; }
  .qiaomu-reader-relayout-ring { animation: none; border-color: color-mix(in srgb, var(--qiaomu-reader-accent) 55%, transparent); border-top-color: var(--qiaomu-reader-accent); border-right-color: color-mix(in srgb, var(--qiaomu-reader-text) 15%, transparent); border-bottom-color: color-mix(in srgb, var(--qiaomu-reader-text) 15%, transparent); }
}

/* ── Reading stats card ──────────────────────────────────────────────────── */
.qiaomu-reader-stats { margin: 2px 0 26px; padding: 18px 18px 14px; border: 1px solid var(--background-modifier-border); border-radius: 12px; background: var(--background-secondary); }
.qiaomu-reader-stats-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.qiaomu-reader-stats-big { font-size: 30px; line-height: 1.1; font-weight: 700; color: var(--text-normal); letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.qiaomu-reader-stats-cap { margin-top: 3px; font-size: 12px; color: var(--text-muted); }
.qiaomu-reader-stats-streak { display: flex; align-items: center; gap: 5px; flex: none; padding: 5px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; color: var(--text-normal); background: color-mix(in srgb, var(--text-accent) 12%, transparent); border: 1px solid color-mix(in srgb, var(--text-accent) 25%, transparent); }
.qiaomu-reader-stats-flame { font-size: 13px; line-height: 1; }

.qiaomu-reader-stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--background-modifier-border); }
.qiaomu-reader-stats-cell { min-width: 0; }
.qiaomu-reader-stats-val { font-size: 15px; font-weight: 600; color: var(--text-normal); font-variant-numeric: tabular-nums; }
.qiaomu-reader-stats-lab { margin-top: 2px; font-size: 11px; color: var(--text-muted); text-transform: lowercase; }

.qiaomu-reader-stats-chart { margin-top: 18px; }
.qiaomu-reader-stats-bars { display: flex; align-items: flex-end; gap: 4px; height: 44px; }
.qiaomu-reader-stats-bar { flex: 1 1 0; min-width: 0; height: 100%; display: flex; align-items: flex-end; }
.qiaomu-reader-stats-fill { width: 100%; border-radius: 3px; background: var(--background-modifier-border); }
.qiaomu-reader-stats-bar.is-read .qiaomu-reader-stats-fill { background: var(--text-muted); }
.qiaomu-reader-stats-bar:last-child.is-read .qiaomu-reader-stats-fill { background: var(--text-accent); }
.qiaomu-reader-stats-legend { display: flex; justify-content: space-between; margin-top: 6px; font-size: 10px; color: var(--text-faint); }
.qiaomu-reader-stats-empty { margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--background-modifier-border); font-size: 12px; color: var(--text-muted); }

/* .qiaomu-reader-col-row is a plain non-wrapping flex row that now also
   carries three- and four-button groups ("left / justify / center /
   right"). A phone panel is full-width yet narrow, so the row wraps instead
   of squeezing labels until they clip. */
.qiaomu-reader-col-row { flex-wrap: wrap; }
.qiaomu-reader-col-row .qiaomu-reader-col-btn { flex: 1 1 auto; min-width: 0; }
.qiaomu-reader-setup-list { max-height: min(280px, 42vh); }

/* ── Welcome-back dialog ─────────────────────────────────────────────────── */
.qiaomu-reader-wn-sub { text-align:center; font-size:12.5px; color:var(--text-muted); margin:-6px 0 14px; font-variant-numeric:tabular-nums; }
.qiaomu-reader-wn-list { text-align:left; display:flex; flex-direction:column; gap:9px; max-height:min(330px, 46vh); overflow-y:auto; padding:2px 2px 2px 0; }
.qiaomu-reader-wn-item { display:grid; grid-template-columns:auto 1fr; gap:9px; align-items:start; }
.qiaomu-reader-wn-dot { color:var(--interactive-accent); font-size:12px; line-height:1.55; padding-top:1px; }
.qiaomu-reader-wn-text { font-size:13.5px; line-height:1.55; color:var(--text-normal); }
.qiaomu-reader-wn-list::-webkit-scrollbar { width:8px; }
.qiaomu-reader-wn-list::-webkit-scrollbar-thumb { background:var(--background-modifier-border); border-radius:8px; }
.qiaomu-reader-onb-tg { display: block; width: fit-content; margin: 12px auto 2px; padding: 9px 18px; border-radius: 999px; font-size: 13px; font-weight: 700; text-decoration: none; color: var(--text-on-accent); background: var(--interactive-accent); transition: background .15s ease; }
.qiaomu-reader-onb-tg:hover { background: var(--interactive-accent-hover); text-decoration: none; }
.qiaomu-reader-wn-cta { text-align: center; margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--background-modifier-border); }
.qiaomu-reader-wn-cta-lead { font-size: 13px; color: var(--text-muted); margin: 0 0 4px; }

/* ── Reader settings modal ───────────────────────────────────────────────── */
.qiaomu-reader-rs-modal { width:min(720px,94vw); max-width:720px; min-width:0; overflow:hidden; }
.qiaomu-reader-rs-modal .modal-content.qiaomu-reader-rs { box-sizing:border-box; width:100%; max-width:100%; min-width:0; max-height:min(78vh,760px); overflow-x:hidden; overflow-y:auto; scrollbar-gutter:stable; overscroll-behavior:contain; padding:2px 14px 8px 2px; }
@supports (overflow:clip) { .qiaomu-reader-rs-modal .modal-content.qiaomu-reader-rs { overflow-x:clip; } }
@supports (height: 100dvh) { .qiaomu-reader-rs { max-height: min(78dvh, 760px); } }
.qiaomu-reader-rs > *, .qiaomu-reader-rs-card, .qiaomu-reader-rs-col, .qiaomu-reader-rs-grid { min-width:0; max-width:100%; box-sizing:border-box; }
.qiaomu-reader-rs-head { display:flex; align-items:center; justify-content:space-between; gap:16px; margin:0 0 14px; }
.qiaomu-reader-rs-title { font-size: 21px; line-height:1.2; font-weight: 650; margin:0; }
.qiaomu-reader-rs-subtitle { margin-top:5px; color:var(--text-muted); font-size:12px; }
.qiaomu-reader-rs-tabs { display:grid; grid-template-columns:repeat(2, minmax(84px, 1fr)); gap:3px; padding:3px; border-radius:10px; background:var(--background-secondary); flex:0 0 auto; }
.qiaomu-reader-rs-tab { min-height:34px; padding:5px 13px; border:0; border-radius:8px; color:var(--text-muted); background:transparent; box-shadow:none; font-size:12.5px; font-weight:550; cursor:pointer; }
.qiaomu-reader-rs-tab:hover { color:var(--text-normal); background:var(--background-modifier-hover); }
.qiaomu-reader-rs-tab.is-active { color:var(--text-normal); background:var(--background-primary); box-shadow:0 1px 4px rgba(0,0,0,.1); }
