.qiaomu-reader-ai-msg-me { align-self: flex-end; border-bottom-right-radius: var(--radius-s); border: 1px solid var(--background-modifier-border); background: var(--background-secondary); color: var(--text-normal); white-space: pre-wrap; }
.qiaomu-reader-ai-msg-context { margin:-2px -2px 7px; border-color:var(--background-modifier-border); background:color-mix(in srgb,var(--background-primary) 72%,transparent); color:var(--text-normal); }
.qiaomu-reader-ai-msg-context summary, .qiaomu-reader-ai-msg-context .qiaomu-reader-ai-context-summary { padding:7px 8px; }
