.qiaomu-reader-lib .qiaomu-reader-lib-book-meta { font-size:11px; font-weight:400; letter-spacing:0; }
.qiaomu-reader-lib .qiaomu-reader-lib-strip { height:3px; }
.qiaomu-reader-lib .qiaomu-reader-lib-strip-fill { background:var(--qiaomu-reader-lib-muted); }
.qiaomu-reader-lib .qiaomu-reader-lib-morebtn, .qiaomu-reader-lib .qiaomu-reader-lib-fitbtn { top:6px; width:28px; height:28px; border-radius:6px; background:var(--qiaomu-reader-lib-bg); color:var(--qiaomu-reader-lib-text); opacity:0; transform:none; }
.qiaomu-reader-lib .qiaomu-reader-lib-card:hover button, .qiaomu-reader-lib .qiaomu-reader-lib-card:focus-within button { opacity:1; }
.qiaomu-reader-lib-study { display:flex; flex-wrap:wrap; gap:2px 8px; margin-top:9px; }
.qiaomu-reader-lib button.qiaomu-reader-lib-study-button { padding:3px 0; height:auto; min-height:28px; font-size:11px; background:none; box-shadow:none; border:0; color:var(--qiaomu-reader-lib-muted); }
.qiaomu-reader-lib button.qiaomu-reader-lib-study-button:hover { color:var(--qiaomu-reader-lib-text); text-decoration:underline; text-underline-offset:3px; }
.qiaomu-reader-lib-resume { grid-column:1/-1; display:flex; align-items:center; gap:24px; padding:18px 20px; margin-bottom:2px; border:1px solid var(--qiaomu-reader-lib-border); border-radius:10px; background:color-mix(in srgb,var(--qiaomu-reader-lib-text) 2%,var(--qiaomu-reader-lib-bg)); }
.qiaomu-reader-lib-resume-copy { flex:1; min-width:0; }
.qiaomu-reader-lib-resume-label { font-size:11px; color:var(--qiaomu-reader-lib-muted); margin-bottom:6px; }
.qiaomu-reader-lib-resume-title { font-size:17px; font-weight:600; white-space:nowrap; text-overflow:ellipsis; overflow:hidden; }
.qiaomu-reader-lib-resume-quote { margin-top:7px; font-size:12px; line-height:1.6; color:var(--qiaomu-reader-lib-muted); white-space:nowrap; text-overflow:ellipsis; overflow:hidden; }
.qiaomu-reader-lib button.qiaomu-reader-lib-resume-button { flex-shrink:0; display:flex; gap:8px; align-items:center; height:36px; padding:0 12px; font-size:12px; color:var(--qiaomu-reader-lib-text); border:1px solid var(--qiaomu-reader-lib-border); background:var(--qiaomu-reader-lib-bg); box-shadow:none; }
.qiaomu-reader-lib-resume-button span { display:flex; }
.qiaomu-reader-lib-resume-button svg { width:14px; height:14px; }
@container (max-width:500px) {
  .qiaomu-reader-lib .qiaomu-reader-lib-hdr { padding:16px 16px 8px; }
  .qiaomu-reader-lib .qiaomu-reader-lib-chips { padding:0 16px; margin-bottom:16px; }
  .qiaomu-reader-lib .qiaomu-reader-lib-grid { padding:0 16px 24px; gap:22px 16px; grid-template-columns:repeat(auto-fill,minmax(130px,1fr)); }
  .qiaomu-reader-lib-resume { padding:14px; gap:12px; flex-wrap:wrap; }
  .qiaomu-reader-lib-resume-copy { flex-basis:100%; }
  .qiaomu-reader-lib .qiaomu-reader-lib-ph-title { font-size:18px; padding-bottom:8px; }
  .qiaomu-reader-lib .qiaomu-reader-lib-study-button { min-height:36px; }
}
@media (hover:none) {
  .qiaomu-reader-lib .qiaomu-reader-lib-morebtn, .qiaomu-reader-lib .qiaomu-reader-lib-fitbtn { opacity:1; }
}

/* Quiet accessible names do not generate Obsidian hover overlays. */
.qiaomu-reader-a11y-label[hidden] { display:none; }
.qiaomu-reader-slider-value { min-width:3ch; font-size:var(--font-ui-small); color:var(--text-muted); font-variant-numeric:tabular-nums; text-align:right; }
.qiaomu-reader-ai-setup > .setting-item { align-items:center; gap:20px; }
.qiaomu-reader-ai-setup > .setting-item .setting-item-control { min-width:0; flex:0 1 62%; }
.qiaomu-reader-ai-setup > .setting-item select { width:100%; max-width:100%; }
.qiaomu-reader-ai-setup-feedback { display:flex; align-items:flex-start; flex-wrap:wrap; gap:8px; font-size:var(--font-ui-small); line-height:1.6; color:var(--text-muted); padding:12px 0; }
.qiaomu-reader-ai-setup-feedback > span:not(.qiaomu-reader-ai-setup-status-icon) { flex:1; min-width:180px; }
.qiaomu-reader-ai-setup-status-icon { display:flex; padding-top:3px; }
.qiaomu-reader-ai-setup-status-icon svg { width:15px; height:15px; }
.qiaomu-reader-ai-setup-feedback button { font-size:var(--font-ui-small); background:var(--background-primary); box-shadow:none; }
.qiaomu-reader-ai-setup .qiaomu-reader-settings-disclosure { margin:12px 0 0; }
.qiaomu-reader-ai-setup .qiaomu-reader-settings-disclosure-body { padding:4px 12px 12px; }
.qiaomu-reader-ai-setup .setting-item-description { line-height:1.5; }
.qiaomu-reader-ai-setup .qiaomu-reader-acp-guide { background:var(--background-secondary); border-color:var(--background-modifier-border); }
.qiaomu-reader-ai-setup .qiaomu-reader-acp-guide-badge { color:var(--text-muted); background:var(--background-primary); }
@media (max-width:520px) {
  .qiaomu-reader-ai-setup > .setting-item { flex-wrap:wrap; gap:8px; }
  .qiaomu-reader-ai-setup > .setting-item .setting-item-control { flex-basis:100%; }
}

/* Five short onboarding steps; release notes retain their own layout. */
.qiaomu-reader-welcome-card { min-height:220px; justify-content:center; }
.qiaomu-reader-onb-icon { display:flex; justify-content:center; color:var(--text-muted); margin:12px 0 20px; }
.qiaomu-reader-onb-icon svg { width:36px; height:36px; }
.qiaomu-reader-onb-dots button.qiaomu-reader-onb-dot { padding:0; border:0; box-shadow:none; height:10px; width:10px; min-width:10px; }
.qiaomu-reader-onb-modal button.qiaomu-reader-onb-skip { display:block; margin:12px auto 0; background:transparent; border:0; box-shadow:none; }

.qiaomu-reader-onb-dots button.qiaomu-reader-onb-dot { background:var(--background-modifier-border); }
.qiaomu-reader-onb-dots button.qiaomu-reader-onb-dot-on { background:var(--text-normal); }

/* Reduced-effects reader mode follows the component cascade. */
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-pdf-page-surface.qiaomu-reader-pdf-rendering::after { animation:none; background:color-mix(in srgb,var(--qiaomu-reader-text,#000) 7%,#fff); }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-lib-drop { border-radius:0; backdrop-filter:none; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-flow { transition: none; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink *, .view-content.qiaomu-reader-view.qiaomu-reader-eink *::before, .view-content.qiaomu-reader-view.qiaomu-reader-eink *::after { transition: none; animation: none; box-shadow: none; text-shadow: none; filter: none; backdrop-filter: none; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-relayouting .qiaomu-reader-area { filter: none; opacity: 1; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-ibtn, .view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-col-btn, .view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-lh-btn, .view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-setup-btn, .view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-act-btn { border: 1px solid #000; border-radius: 0; opacity: 1; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-col-btn.active, .view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-lh-btn.active { background: #000; color: #fff; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-veil-line { animation: none; opacity: .12; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-area { transition: none; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-note-back { animation: none; box-shadow: none; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-lib-strip { background: #000; }
.view-content.qiaomu-reader-view.qiaomu-reader-eink .qiaomu-reader-lib-card { animation: none; }

/* Companion setup shares the sidebar surface and scrolls independently. */
.qiaomu-reader-companion-setup { overflow-y: auto; min-height: 0; padding: 0 4px 16px; }
.qiaomu-reader-companion-setup > p { color: var(--text-muted); font-size: var(--font-ui-small); }
.qiaomu-reader-companion-setup .setting-item { flex-wrap: wrap; gap: 8px; }
.qiaomu-reader-companion-setup .setting-item-control { flex: 1 1 100%; justify-content: flex-start; min-width: 0; }
.qiaomu-reader-companion-setup select, .qiaomu-reader-companion-setup input { max-width: 100%; }
.qiaomu-reader-companion-start { width: 100%; margin-top: 12px; }
.qiaomu-reader-translation-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; margin-top: 16px; }
.qiaomu-reader-translation-save { display: flex; gap: 2px; }
.qiaomu-reader-translation-save svg { width: 16px; height: 16px; }
.qiaomu-reader-translation-status { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; color: var(--text-muted); font-size: var(--font-ui-small); margin-top: 12px; }

.qiaomu-reader-ai-attachment-status { display:flex; align-items:center; gap:8px; padding:6px 0; font-size:var(--font-ui-small); color:var(--text-muted); }
.qiaomu-reader-ai-attachment-status[hidden] { display:none; }
.qiaomu-reader-sr-only { position:absolute; width:1px; height:1px; padding:0; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }

.qiaomu-reader-note-folder-field { display:grid; grid-template-columns:minmax(0, 1fr) auto; gap:6px; }
.qiaomu-reader-note-folder-field .qiaomu-reader-setup-label { grid-column:1 / -1; }

/* Keep explicit night reading local to its view, even in a light vault. */
.qiaomu-reader-night {
  color-scheme: dark;
  --background-primary: #181a1b;
  --background-primary-alt: #222526;
  --background-secondary: #222526;
  --background-secondary-alt: #181a1b;
  --background-modifier-border: #383c3d;
  --background-modifier-hover: #303536;
  --background-modifier-form-field: #222526;
  --text-normal: #d9d7d1;
  --text-muted: #9a9a94;
  --text-faint: #858b87;
  --interactive-normal: #222526;
  --interactive-hover: #303536;
  --interactive-accent: #91ab9a;
  --text-on-accent: #181a1b;
  color: var(--text-normal);
}

